import base64, os
b64 = ""
target = os.path.expanduser('~/mnt/origem-outdoor/src/pages/Contratos.js')
data = base64.b64decode(b64).decode('utf-8')
with open(target, 'w', encoding='utf-8') as f:
    f.write(data)
print("Escrito:", len(data), "chars")
with open(target, 'r', encoding='utf-8') as f:
    check = f.read()
print("Verificado:", len(check), "chars")
print("placaDatas:", check.count("placaDatas"))
